parameters.jsCode:
const raw = $input.first().json.choices[0].message.content;

const clean = raw
  .replace(/```json\n?/g, '')
  .replace(/```/g, '')
  .trim();

let plan;
try {
  plan = JSON.parse(clean);
} catch(e) {
  throw new Error('Groq no devolvio JSON valido: ' + clean.substring(0, 200));
}

const webhookData = $('Webhook Registro').first().json.body;

return [{
  json: {
    userId: webhookData.userId,
    plan: {
      meta:   plan.meta,
      rutina: plan.rutina,
      dieta:  plan.dieta
    }
  }
}];

// Archivar plan activo anterior y calcular versión
// N8N no puede hacer updateOne directamente con lógica condicional
// así que preparamos el documento a insertar con versión 1 por defecto
// El backend ya no guarda — solo N8N guarda

const data = $input.first().json;

return [{
  json: {
    userId:  data.userId,
    version: 1,
    estado:  'activo',
    meta:    data.plan.meta,
    rutina:  data.plan.rutina,
    dieta:   data.plan.dieta,
    plan:    data.plan
  }
}];
